(* [comment removed for export] *)
Lemma XStatics_keep : forall W m m',
  XStatics m -> munch W m m' -> wmono rsegs m m' ->
  Forall (fun iv : Z * Z => 0xb4000 <= fst iv \/ snd iv <= 0x10000) W -> XStatics m'.
Proof.
  intros W m m' XS MU WM FW. eapply XStatics_transport; [exact XS| exact MU| exact WM|].
  eapply Forall_impl; [| exact FW]. intros [lo hi] K; cbn in *. lia.
Qed.

(* [comment removed for export] *)
Lemma cookie_fold : forall m C cs,
  rw_cells rsegs m C cs -> cells_size cs = 15%nat -> firstn 8 (cells_bytes cs) = zeros 8 ->
  rw_cells rsegs m C (CookieCells (skipn 8 (cells_bytes cs))).
Proof.
  intros m C cs RC SZ F8. pose proof RC as [[WF _] _]. pose proof (cells_bytes_length cs WF) as L. rewrite SZ in L.
  eapply rw_cells_reshape; [exact RC| |].
  - cbn. rewrite length_skipn. repeat split; lia.
  - unfold CookieCells. cbn [cells_bytes cbytes app]. rewrite app_nil_r, <- F8. apply firstn_skipn.
Qed.

(* [comment removed for export] *)
Lemma cookie_unfold : forall m C j7, rw_cells rsegs m C (CookieCells j7) ->
  rw_cells rsegs m C [C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); CB 7 j7].
Proof.
  intros m C j7 RC. pose proof RC as [[WF _] _]. cbn in WF.
  eapply rw_cells_reshape; [exact RC| cbn; repeat split; lia| reflexivity].
Qed.

