Lemma ro_cells_rheap_pres : forall LB SP m m' A cs,
  rheap_pres LB SP m m' -> ro_cells rsegs m A cs -> rclient_range LB SP A (Z.of_nat (cells_size cs)) -> ro_cells rsegs m' A cs.
Proof.
  intros LB SP m m' A cs HP [Hwf HB] HR. split; [exact Hwf|].
  eapply rheap_pres_bytes_at; eauto. rewrite cells_bytes_length by assumption. exact HR.
Qed.

(* [comment removed for export] *)
Definition dobj_entry_ok (E : Z) : Prop := E = P_DEALLOC_OBJ_CONFIG \/ E = P_DEALLOC_OBJ_SCHED \/ E = P_DEALLOC_OBJ_SSVC.
Definition dobj_size (E : Z) : Z := if E =? P_DEALLOC_OBJ_CONFIG then SZ_CFG else if E =? P_DEALLOC_OBJ_SCHED then SZ_SCH else SZ_SSVC.
Definition dobj_vp (E : Z) : Z := if E =? P_DEALLOC_OBJ_CONFIG then VP_CONFIG_SVC else if E =? P_DEALLOC_OBJ_SCHED then VP_SCHED else VP_SSVC.
Definition dobj_dtor (E : Z) : Z := if E =? P_DEALLOC_OBJ_CONFIG then P_NONCOPYABLE_DTOR else if E =? P_DEALLOC_OBJ_SCHED then P_SCHED_DTOR else P_SSVC_DTOR.
(* [comment removed for export] *)
Definition dobj_epi_ok (pcC : Z) : Prop :=
  pcC = P_DEALLOC_OBJ_CONFIG + 68 \/ pcC = P_DEALLOC_OBJ_SCHED + 68 \/ pcC = P_DEALLOC_OBJ_SSVC + 68 \/ pcC = P_DEALLOC_OBJ_REGISTRY + 60.
Lemma dobj_epi_of_entry : forall E, dobj_entry_ok E -> dobj_epi_ok (E + 68).
Proof. intros E [-> |[-> | ->]]; unfold dobj_epi_ok; auto. Qed.

Definition P_ALLOCATE_RET1 : Z := 0x2d060.   (* [comment removed for export] *)
Definition DOBJ_STACK : Z := 32 + RFREE_STACK.          (* [comment removed for export] *)
Definition DALL_STACK : Z := 16 + DOBJ_STACK.           (* [comment removed for export] *)
Definition DEALLOCATE_STACK : Z := RFREE_STACK.        (* [comment removed for export] *)
Definition ALLOCIMPL_DESTROY_STACK : Z := RFREE_STACK.  (* [comment removed for export] *)
Definition P_ALLOCIMPL_DESTROY_RET1 : Z := 0x2d018.
Definition ALLOCATE_STACK : Z := 64 + ROPNEW_STACK.

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

(* [comment removed for export] *)
(* [comment removed for export] *)

  (* [comment removed for export] *)
  Definition alloc_seg1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (size lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' junk,
      ms' = MS (mkR (Z_to_bv 64 P_ALLOCATE_RET1) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2
                    (Z_to_bv 64 size) s1 (Z_to_bv 64 (size + 15)) (Z_to_bv 64 (size + 7)) a2 a3 a4 a5 a6 a7
                    (Z_to_bv 64 8) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 ROPNEW) fc None m' (seg_rom rsegs)
      /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp + -64)
      /\ rw_cells rsegs m' (bv_unsigned sp + -64) [CB 24 junk; C8 (Z_to_bv 64 (size + 7)); C8 s2; C8 s1; C8 s0; C8 ra].
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.

  Lemma alloc_seg1 : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (size lo : Z),
    stk rsegs m lo (bv_unsigned sp) -> lo + 64 <= bv_unsigned sp ->
    0 <= size -> size + 15 < 2^32 ->
    mem_inv rsegs m ->
    evt rsegs (alloc_seg1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc size lo m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 size) (Z_to_bv 64 8) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
