  Definition alloc_seg2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (A size lo : Z) (junkB : list byte) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j7,
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ munch [(lo, bv_unsigned sp); (A, A + (size + 15))]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' A [CB (Z.to_nat size) (firstn (Z.to_nat size) junkB)]
      /\ rw_cells rsegs m' (A + size) (CookieCells j7).
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

  Lemma alloc_seg2 : forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (A size lo : Z) (s1x : word) (junkF junkB : list byte),
    rw_cells rsegs m (bv_unsigned sp + -64) [CB 24 junkF; C8 (Z_to_bv 64 (size + 7)); C8 s2; C8 s1; C8 s0; C8 ra] ->
    rw_cells rsegs m A [CB (Z.to_nat (size + 15)) junkB] ->
    stk rsegs m lo (bv_unsigned sp + -64) -> lo + 64 <= bv_unsigned sp ->
    rblock_range A (size + 15) -> hceil <= lo ->
    0 <= size -> size + 15 < 2^32 ->
    mem_inv rsegs m ->
    evt rsegs (alloc_seg2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A size lo junkB m)
      (MS (mkR (Z_to_bv 64 P_ALLOCATE_RET1) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2
               (Z_to_bv 64 size) s1x (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7
               (Z_to_bv 64 8) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 P_ALLOCATE_RET1) fc None m (seg_rom rsegs)).
