  Definition dobj_segA_post (sp gp tp t0 t1 t2 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
      (E pobj allocb lo : Z) (ra s0 s1 : word) (m : mem) : machine_state -> Prop :=
    fun ms' => exists m' junk,
      ms' = MS (mkR (Z_to_bv 64 (E + 40)) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2
                    (Z_to_bv 64 pobj) (Z_to_bv 64 allocb) (Z_to_bv 64 pobj) (Z_to_bv 64 (dobj_dtor E)) a2 a3 a4 a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 (dobj_dtor E)) fc None m' (seg_rom rsegs)
      /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp + -32)
      /\ rw_cells rsegs m' (bv_unsigned sp + -32) [CB 8 junk; C8 s1; C8 s0; C8 ra].
Scheme kc__5 := Elimination for Corelib.Init.Logic.or Sort Prop.

  Lemma dobj_segA : forall (E : Z), dobj_entry_ok E ->
    forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (AT pobj allocb lo : Z),
    ro_cells rsegs m AT [C8 (wz allocb)] -> ro_cells rsegs m pobj [C8 (wz (dobj_vp E))] -> XStatics m ->
    stk rsegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> hceil <= lo ->
