  (* [comment removed for export] *)
  Definition dobj_segB_post (ra sp gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
      (E pobj allocb : Z) (m : mem) : machine_state -> Prop :=
    fun ms' =>
      ms' = MS (mkR (Z_to_bv 64 (E + 68)) sp gp tp t0 t1 t2 s0 s1
                    (Z_to_bv 64 allocb) (Z_to_bv 64 pobj) (Z_to_bv 64 (dobj_size E)) (Z_to_bv 64 8) (Z_to_bv 64 P_ALLOCIMPL_DEALLOCATE) a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_ALLOCIMPL_DEALLOCATE) fc None m (seg_rom rsegs)
      /\ munch [] m m /\ wmono rsegs m m /\ mem_inv rsegs m.

  Lemma dobj_segB : forall (E : Z), dobj_entry_ok E ->
