  Definition dreg_segA_post (sp gp tp t0 t1 t2 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
      (r allocb lo : Z) (ra s0 s1 : word) (m : mem) : machine_state -> Prop :=
    fun ms' => exists a5 a6 a7 m' junk,
      ms' = MS (mkR (Z_to_bv 64 (P_DEALLOC_OBJ_REGISTRY + 60)) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2
                    (Z_to_bv 64 allocb) (Z_to_bv 64 r)
                    (Z_to_bv 64 allocb) (Z_to_bv 64 r) (Z_to_bv 64 SZ_REG) (Z_to_bv 64 8) (Z_to_bv 64 P_ALLOCIMPL_DEALLOCATE) a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_ALLOCIMPL_DEALLOCATE) fc None m' (seg_rom rsegs)
      /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp + -32)
      /\ rw_cells rsegs m' (bv_unsigned sp + -32) [CB 8 junk; C8 s1; C8 s0; C8 ra].

  Lemma dreg_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (AT r allocb lk lo : Z),
    ro_cells rsegs m AT [C8 (wz allocb)] -> PMutex m (r + O_REG_MUTEX) lk ->
    ro_cells rsegs m allocb [C8 (wz VP_ALLOCIMPL)] -> XStatics m ->
    stk rsegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> hceil <= lo ->
    (AT + 8 <= lo \/ bv_unsigned sp <= AT) -> (r + NEWSZ_REG <= lo \/ bv_unsigned sp <= r) -> (allocb + 8 <= lo \/ bv_unsigned sp <= allocb) ->
    0 <= r -> r + NEWSZ_REG <= 2^64 ->
    mem_inv rsegs m ->
    evt rsegs (dreg_segA_post sp gp tp t0 t1 t2 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc r allocb lo ra s0 s1 m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 AT) (Z_to_bv 64 r) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 P_DEALLOC_OBJ_REGISTRY) fc None m (seg_rom rsegs)).
