  (* [comment removed for export] *)
  Definition dall_segC_post (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
      (lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' =>
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m (seg_rom rsegs)
      /\ munch [] m m /\ wmono rsegs m m /\ mem_inv rsegs m
      /\ stk rsegs m lo (bv_unsigned sp).

  Lemma dall_segC : forall (E' : Z), dall_entry_ok E' ->
    forall (rax : word) sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (ra c0 : word)
      (F : bvmap 5 word) fc (m : mem) (lo : Z),
    rw_cells rsegs m (bv_unsigned sp + -16) [C8 c0; C8 ra] ->
    stk rsegs m lo (bv_unsigned sp + -16) -> lo + 16 <= bv_unsigned sp ->
    mem_inv rsegs m ->
    evt rsegs (dall_segC_post ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc lo m)
      (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 (E' + 32)) fc None m (seg_rom rsegs)).
